        XCTAssertTrue(app.buttons["viewMenu.row.0"].waitForNonExistence(timeout: 5), "Deleting a view should remove it from the dropdown")
        XCTAssertEqual(app.buttons["viewMenu.row.all"].value as? String, "1",
