    /// Merge Down flattens a layer into the one below it, leaving a single layer behind. Same model
    /// call the two-finger pinch gesture makes.
    func testMergeDownFlattensTwoLayersIntoOne() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))

        let canvas = app.otherElements["canvas.host"]
        XCTAssertTrue(canvas.waitForExistence(timeout: 5))
        let point = safeOutsideCornerPoint(canvas)
        drawLine(on: canvas, from: point, to: CGVector(dx: point.dx + 0.12, dy: point.dy))

        openLayerPanel(app)
        let addLayer = app.buttons["layerPanel.addButton"]
        XCTAssertTrue(addLayer.waitForExistence(timeout: 5)) // the panel has to finish presenting first
        addLayer.tap() // layers: [Vector 1 (drawn on), Vector 2]
        XCTAssertTrue(app.staticTexts["layerPanel.row.1"].waitForExistence(timeout: 5))

        let top = app.staticTexts["layerPanel.row.1"]
        top.tap()
        top.tap()
        let mergeDown = app.buttons["layerOptions.mergeDown"]
        XCTAssertTrue(mergeDown.waitForExistence(timeout: 5))
        mergeDown.tap()

        XCTAssertTrue(app.staticTexts["layerPanel.row.1"].waitForNonExistence(timeout: 5),
                      "Merging should leave exactly one layer")
        XCTAssertTrue(app.staticTexts["layerPanel.row.0"].waitForExistence(timeout: 5))
        XCTAssertEqual(readHasBakedImage(app, layerIndex: 0), false,
                       "The surviving layer should hold the flattened pixels in the raster tier, not a separate baked-image tier")
        XCTAssertEqual(readLayerStrokeCount(app, layerIndex: 0), 1,
                       "The flattened pixels of both layers should register as raster content")
        XCTAssertFalse(isWhitish(rgbaPixel(of: canvas, dx: point.dx + 0.06, dy: point.dy)),
                       "The merged artwork should still be on the canvas")
    }

    /// Merging a vector layer must leave the survivor as a genuine `.raster` layer, not `.vector`
    /// with emptied-out geometry — the inconsistency `rasterizeLayer` exists to prevent.
    func testMergeDownFromVectorLayerRasterizesTheSurvivor() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))

        app.buttons["toolbar.layersButton"].tap()
        let addButton = app.buttons["layerPanel.addButton"]
        XCTAssertTrue(addButton.waitForExistence(timeout: 5))
        addButton.press(forDuration: 1.2)
        let vectorItem = app.buttons["Vector Layer"]
        XCTAssertTrue(vectorItem.waitForExistence(timeout: 5))
        vectorItem.tap() // layers: [Vector 1, Vector 2 (active)]
        app.buttons["toolbar.layersButton"].tap() // close panel

        let canvas = app.otherElements["canvas.host"]
        XCTAssertTrue(canvas.waitForExistence(timeout: 5))
        drawLine(on: canvas, from: CGVector(dx: 0.3, dy: 0.5), to: CGVector(dx: 0.7, dy: 0.5))

        app.buttons["toolbar.layersButton"].tap()
        XCTAssertEqual(readVectorMarker(app, layerIndex: 1)?.isVector, true, "Setup: should be a vector layer")
        // Raster has to be asked for by name now that the plain `+` makes a vector layer, and a
        // raster layer on top is the whole premise: this test is about what merging one *into* a
        // vector layer leaves behind.
        addButton.press(forDuration: 1.2)
        let rasterItem = app.buttons["Raster Layer"]
        XCTAssertTrue(rasterItem.waitForExistence(timeout: 5), "The add menu should still offer a Raster Layer option")
        rasterItem.tap() // layers: [Vector 1, Vector 2, Layer 3 (active, raster, on top)]
        XCTAssertTrue(app.staticTexts["layerPanel.row.2"].waitForExistence(timeout: 5))

        let top = app.staticTexts["layerPanel.row.2"]
        top.tap()
        top.tap()
        let mergeDown = app.buttons["layerOptions.mergeDown"]
        XCTAssertTrue(mergeDown.waitForExistence(timeout: 5))
        mergeDown.tap() // merges Layer 3 into the vector layer below it

        XCTAssertTrue(app.staticTexts["layerPanel.row.2"].waitForNonExistence(timeout: 5))
        XCTAssertEqual(readVectorMarker(app, layerIndex: 1)?.isVector, false,
                       "The survivor should come out of the merge as a raster layer, not vector with emptied geometry")
        XCTAssertEqual(readHasBakedImage(app, layerIndex: 1), false, "The survivor should hold the flattened pixels in the raster tier, not a separate baked-image tier")
        XCTAssertEqual(readLayerStrokeCount(app, layerIndex: 1), 1, "The flattened pixels should register as raster content")
        app.buttons["toolbar.layersButton"].tap() // close panel

        XCTAssertFalse(isWhitish(rgbaPixel(of: canvas, dx: 0.5, dy: 0.5)), "The vector stroke should survive the merge")
    }

    // MARK: - §4.1/§4.2 group properties

    /// The regression phase 4b exists to fix: `toggleFolderVisibility` stopped writing through to
    /// children (§4.1), so the live canvas has to consult `isLayerEffectivelyVisible` per layer
    /// instead of the layer's own flag, or hiding a group does nothing on screen.
    func testHidingFolderHidesContentsOnCanvasAndReshowingRestoresThem() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))

        let canvas = app.otherElements["canvas.host"]
        XCTAssertTrue(canvas.waitForExistence(timeout: 5))
        let point = safeOutsideCornerPoint(canvas)
        drawLine(on: canvas, from: point, to: CGVector(dx: point.dx + 0.12, dy: point.dy))
        XCTAssertFalse(isWhitish(rgbaPixel(of: canvas, dx: point.dx + 0.06, dy: point.dy)),
                       "Setup: the stroke should be on the canvas")

        openLayerPanel(app)
        addFolderFromAddMenu(app) // Folder 1, empty, at the top
        dragRow(layerCell(app, layerIndex: 0), onto: folderCell(app, named: "Folder 1"), dropDY: 0.5)
        XCTAssertEqual(rowFolder(app, layerIndex: 0), "Folder 1", "Setup: the drawn layer should now be inside the folder")

        app.buttons["layerPanel.folder.Folder 1.visibility"].tap()
        app.buttons["toolbar.layersButton"].tap() // close panel to see the canvas

        XCTAssertTrue(waitUntilBlank(canvas, dx: point.dx + 0.06, dy: point.dy, timeout: 5),
                      "Hiding the folder should hide its contents on the live canvas, not just in the panel")

        app.buttons["toolbar.layersButton"].tap() // reopen
        app.buttons["layerPanel.folder.Folder 1.visibility"].tap() // show again
        app.buttons["toolbar.layersButton"].tap() // close

        XCTAssertTrue(waitUntilFilled(canvas, dx: point.dx + 0.06, dy: point.dy, timeout: 5),
                      "Re-showing the folder should restore its contents")
    }

    /// A folder row's tap already means expand/collapse, so its options — the pass-through toggle
    /// (§4.2) and Rename — live behind the row's own button instead of "tap the already-selected
    /// row again", which is how a layer row opens the same menu.
    func testFolderOptionsButtonOpensPassThroughToggleOffByDefault() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)
        addFolderFromAddMenu(app)
        XCTAssertTrue(app.staticTexts["layerPanel.folder.Folder 1"].waitForExistence(timeout: 5))
        XCTAssertFalse(app.switches["layerOptions.passThroughToggle"].exists,
                       "The options menu should not be showing before the button is tapped")

        app.buttons["layerPanel.folder.Folder 1.options"].tap()

        let toggle = app.switches["layerOptions.passThroughToggle"]
        XCTAssertTrue(toggle.waitForExistence(timeout: 5), "Tapping the folder's options button should open its menu")
        XCTAssertEqual(toggle.value as? String, "0", "Isolated is the default (§4.2), so Pass Through starts off")

        // Hit the switch itself — tapping a SwiftUI Toggle's label doesn't flip it.
        toggle.coordinate(withNormalizedOffset: CGVector(dx: 0.93, dy: 0.5)).tap()
        XCTAssertEqual(toggle.value as? String, "1", "Toggling should flip the switch")

        // Close and reopen to confirm the flip reached the model (`setFolderIsolated`), not just
        // the switch's own transient state.
        app.buttons["layerOptions.close"].tap()
        app.buttons["layerPanel.folder.Folder 1.options"].tap()
        XCTAssertEqual(app.switches["layerOptions.passThroughToggle"].value as? String, "1",
                       "The toggle should reflect the folder's isIsolated flag, not reset when the panel reopens")
    }

    /// Folder rows get the same opacity slider layer rows already have (§4.1), routed through
    /// `CanvasManager.setFolderOpacity` rather than the raw `layers[i].opacity = value` write the
    /// layer rows use (folders have no such index).
    func testFolderOpacitySliderPersistsThroughSetFolderOpacity() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)
        addFolderFromAddMenu(app)
        XCTAssertTrue(app.staticTexts["layerPanel.folder.Folder 1"].waitForExistence(timeout: 5))

        let slider = app.sliders["layerPanel.folder.Folder 1.opacity"]
        XCTAssertTrue(slider.waitForExistence(timeout: 5), "Folder rows should show the same opacity slider layer rows have")
        XCTAssertEqual(sliderNumericValue(slider), 100, "A fresh folder starts at full opacity")

        slider.adjust(toNormalizedSliderPosition: 0.3)
        let after = sliderNumericValue(slider)
        XCTAssertLessThan(after, 100, "Dragging the slider down should lower the folder's opacity")

        // Collapsing and re-expanding forces a fresh `configure()` from the model, which only
        // shows the dragged value if it reached `setFolderOpacity` rather than staying local to
        // the control (folder rows have no per-layer index for a raw write to land on).
        app.staticTexts["layerPanel.folder.Folder 1"].tap() // collapse
        app.staticTexts["layerPanel.folder.Folder 1"].tap() // expand
        XCTAssertEqual(sliderNumericValue(app.sliders["layerPanel.folder.Folder 1.opacity"]), after, accuracy: 1,
                       "The opacity should persist on the model, not reset when the row is reconfigured")
    }

    // MARK: - §7 blend modes

    /// The picker (`blendModeRow` in LayerPanel.swift) is a `Menu` grouped by `BlendMode.menuGroups`;
    /// picking an item should reach `CanvasManager.setLayerBlendMode` — not stay local to the control
    /// — show on the row without closing the options panel (§7's whole point: a mode has to be
    /// readable without opening options), and survive the panel closing and reopening.
    func testSettingLayerBlendModeShowsOnRowAndPersists() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)

        let row = app.staticTexts["layerPanel.row.0"]
        XCTAssertTrue(row.waitForExistence(timeout: 5))
        row.tap() // select
        row.tap() // open options

        let picker = app.buttons["layerOptions.blendModeButton"]
        XCTAssertTrue(picker.waitForExistence(timeout: 5))
        XCTAssertEqual(picker.value as? String, "normal", "A fresh layer starts at Normal")

        let rowBlendMode = app.otherElements["layerPanel.row.0.blendMode"]
        XCTAssertEqual(rowBlendMode.value as? String, "normal", "Setup: the row's own marker should agree")

        picker.tap()
        let multiply = app.buttons["layerOptions.blendMode.multiply"]
        XCTAssertTrue(multiply.waitForExistence(timeout: 5), "The menu should list Multiply, grouped under darkening (§7)")
        multiply.tap()

        XCTAssertEqual(picker.value as? String, "multiply", "Picking a mode should update the button's own state")
        XCTAssertEqual(rowBlendMode.value as? String, "multiply",
                       "The row should reflect the new mode immediately — LayerRowModel.blendMode is part of its Equatable conformance, so the diffable data source reconfigures the cell")

        // Close and reopen to confirm the pick reached `setLayerBlendMode`, not just local control state.
        app.buttons["layerOptions.close"].tap()
        row.tap()
        row.tap()
        XCTAssertEqual(app.buttons["layerOptions.blendModeButton"].value as? String, "multiply",
                       "The picker should reflect the layer's blendMode, not reset when the panel reopens")
    }

    /// Same contract as the layer picker above, routed through `setFolderBlendMode` instead — the
    /// group side of §7, which is the same picker (`blendModeRow`) reused rather than a second one.
    func testSettingFolderBlendModeShowsOnRowAndPersists() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)
        addFolderFromAddMenu(app)
        XCTAssertTrue(app.staticTexts["layerPanel.folder.Folder 1"].waitForExistence(timeout: 5))

        app.buttons["layerPanel.folder.Folder 1.options"].tap()
        let picker = app.buttons["layerOptions.blendModeButton"]
        XCTAssertTrue(picker.waitForExistence(timeout: 5))
